import React, { useEffect, useState } from "react";
import AdminNavbar from "../Components/AdminNavbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/AdminPages.css";

const Reports = () => {
  const [reports, setReports] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/admin/reports`)
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setReports(data);
        }
      })
      .catch((err) => console.error("Failed to fetch reports:", err));
  }, []);
  const markAsReviewed = async (id) => {
    const res = await fetch(`${API_BASE_URL}/api/admin/reports/${id}/review`, {
      method: "PUT",
    });
    if (res.ok) {
      setReports((prev) =>
        prev.map((r) => (r.id === id ? { ...r, reviewed: true } : r))
      );
    }
  };
  
  const deleteReport = async (id) => {
    if (!window.confirm("Are you sure you want to delete this report?")) return;
    const res = await fetch(`${API_BASE_URL}/api/admin/reports/${id}`, {
      method: "DELETE",
    });
    if (res.ok) {
      setReports((prev) => prev.filter((r) => r.id !== id));
    }
  };
  

  return (
    <>
      <AdminNavbar />
      <div className="admin-wrapper">
        <h2 className="admin-title">User Reports</h2>

        {reports.length === 0 ? (
          <p>No user reports submitted.</p>
        ) : (
          <div className="reports-grid">
            {reports.map((report) => (
  <div key={report.id} className="report-card">
    <p><strong>Reported User:</strong> {report.reported_username}</p>
    <p><strong>Reason:</strong> {report.reason}</p>
    <p><strong>Reporter:</strong> {report.reporter_username}</p>
    <p><small>{new Date(report.created_at).toLocaleString()}</small></p>
    <p><strong>Status:</strong> {report.reviewed ? "✅ Reviewed" : "🕓 Unreviewed"}</p>

    <div className="report-actions">
      {!report.reviewed && (
        <button onClick={() => markAsReviewed(report.id)}>Mark as Reviewed</button>
      )}
      <button onClick={() => deleteReport(report.id)}>Delete</button>
    </div>
  </div>
))}

          </div>
        )}
      </div>
      <Footer />
    </>
  );
};

export default Reports;
